import React from 'react';

/**
 * A stable id for an element: `idOverride` when given, else one generated by React, with an optional prefix.
 *
 * @example
 * ```tsx
 * <div id={useId()} />
 * ```
 *
 * @param idOverride - An id to use instead of the generated one.
 * @param prefix - A prefix for the generated id.
 * @returns The id.
 */
export function useId(idOverride?: string, prefix?: string): string | undefined {
    const reactId = React.useId();

    return idOverride ?? (prefix ? `${prefix}-${reactId}` : reactId);
}
